{"command": "cd /workspace/vllm-project/vllm && python - <<'PY'
from pathlib import Path
import json
p=Path('vllm/attention/ops/triton_unified_attention.py')
lines=p.read_text().splitlines()
start=None
end=None
for i,l in enumerate(lines):
    if l.startswith('def kernel_unified_attention_2d(') or l.startswith('@triton.jit') and i+1 < len(lines) and lines[i+1].startswith('def kernel_unified_attention_2d('):
        start=i
        break
if start is None:
    raise SystemExit('start not found')
# ensure include decorator
if lines[start].startswith('def '):
    start-=1
for i in range(start+1,len(lines)):
    if lines[i].startswith('@triton.jit') and 'kernel_unified_attention_3d' in lines[i+1]:
        end=i
        break
if end is None:
    raise SystemExit('end not found')
body='\n'.join(lines[start:end]).rstrip()+'\n'
out={"vllm/attention/ops/triton_unified_attention.py":{"kernel_unified_attention_2d":body}}
Path('/prediction.json').write_text(json.dumps(out, indent=4))
print('wrote /prediction.json')
PY"}

